function validate([jobs, workers]) {
  if (jobs.length !== workers.length) return 'jobs and workers must have the same length.';
  if (jobs.length < 1 || jobs.length > 100000) return 'There must be 1 to 100000 jobs.';
  if (jobs.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each job time is an integer from 1 to 100000.';
  if (workers.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each worker capacity is an integer from 1 to 100000.';
  return null;
}

