function minimumTime(jobs, workers) {
  jobs.sort((a, b) => a - b);
  workers.sort((a, b) => a - b);
  let days = 0;

  for (let i = 0; i < jobs.length; i++) {
    const needed = Math.ceil(jobs[i] / workers[i]);
    if (needed > days) {
      days = needed;
    }
  }
  return days;
}

