function minimumTime(jobs, workers) {
  // Try every way to hand the jobs to the workers.
  const n = jobs.length;
  const used = new Array(n).fill(false);
  let best = Infinity;
  const assign = (j, worst) => {
    if (worst >= best) return;
    if (j === n) { best = worst; return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      let d = 0;
      while (d * workers[j] < jobs[i]) d++;
      assign(j + 1, Math.max(worst, d));
      used[i] = false;
    }
  };
  assign(0, 0);
  return best;
}

