function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const jobTop = rand() < 0.5 ? 100000 : 1000;
    const workerTop = rand() < 0.5 ? 100000 : 100;
    const jobs = Array.from({ length: n }, () => 1 + Math.floor(rand() * jobTop));
    const workers = Array.from({ length: n }, () => 1 + Math.floor(rand() * workerTop));
    return [jobs, workers];
  }
  const n = 1 + Math.floor(rand() * 6);
  const top = rand() < 0.5 ? 6 : 30;
  const jobs = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const workers = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [jobs, workers];
}
